请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-003

=== 用户原始指令 (query.txt) ===
整个防沉迷的吧,一行带数字的话,点进设置操作,提醒我快不行了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个防沉迷的吧,一行带数字的话,点进设置操作,提醒我快不行了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "antiAddiction": {
      "title": {
        "type": "string",
        "description": "防沉迷或健康使用提醒标题",
        "sampleValue": "健康使用提醒"
      },
      "statusLabel": {
        "type": "string",
        "description": "当前防沉迷状态短标签",
        "sampleValue": "预警"
      },
      "remainingText": {
        "type": "string",
        "description": "今日剩余可用时长的数字展示文本",
        "sampleValue": "12分钟"
      },
      "primaryCaption": {
        "type": "string",
        "description": "主数值的含义说明",
        "sampleValue": "剩余可用时间"
      },
      "progressValue": {
        "type": "number",
        "description": "今日已使用时长分钟数，用于展示接近限制的进度",
        "sampleValue": 108
      },
      "progressTotal": {
        "type": "number",
        "description": "今日可用时长上限分钟数，用于展示进度总量",
        "sampleValue": 120
      },
      "usageSummary": {
        "type": "string",
        "description": "今日已用和限制的摘要文本",
        "sampleValue": "今日已用108/120分钟"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入健康使用设置的短操作文案",
        "sampleValue": "进入设置"
      },
      "actionHint": {
        "type": "string",
        "description": "接近限制时建议调整设置的提醒文案",
        "sampleValue": "接近限制，请调整时长"
      }
    }
  },
  "assetCandidates": []
}

